    const real=realOrdersForSelection(),complete=real.filter(o=>o.costComplete),missing=real.filter(o=>!o.costComplete).length,revenue=real.reduce((sum,o)=>sum+Number(o.total||0),0),returns=real.reduce((sum,o)=>sum+Number(o.refund||0),0),netSales=revenue-returns,cogs=complete.reduce((sum,o)=>sum+o.product,0),shipping=complete.reduce((sum,o)=>sum+o.shipping,0),fees=complete.reduce((sum,o)=>sum+o.fees,0),profit=complete.reduce((sum,o)=>sum+o.total-o.refund-o.product-o.shipping-o.fees,0),sourceLabel=state.store==='zroyal'?'SHOPIFY LIVE':state.store==='all'?'SHOPIFY + ETSY + Supplier':'ETSY + Supplier';
