function renderAccount(){const ids=accounts[state.client].stores;$('[data-store-health]').innerHTML=ids.map((id,index)=>{const store=stores[id],score=Math.max(71,94-index*7+(id==='north'?-8:0));return`<button class="store-health-card" type="button" data-account-store="${id}"><span><b>${store.name}</b><small>${store.platformName} · ${store.status}</small></span><strong>${score}</strong><i style="--health:${score}%"></i></button>`}).join('');$('[data-store-compare]').innerHTML=ids.map((id,index)=>{const store=stores[id],revenue=base.revenue*store.factor*rangeMultiplier(),profit=revenue*(.25-index*.018),ordersCount=Math.round(base.orders*store.factor*rangeMultiplier()),roas=(4.62-index*.57).toFixed(2),refunds=(1.2+index*.7).toFixed(1),status=id==='north'?'Needs attention':'OK';return`<tr><td><button type="button" class="store-link" data-account-store="${id}"><b>${store.name}</b><small>${store.platformName}</small></button></td><td class="mono">${money(revenue)}</td><td class="mono positive">${money(profit)}</td><td class="mono">${roas}x</td><td class="mono">${ordersCount.toLocaleString()}</td><td class="mono">${refunds}%</td><td><span class="status ${status==='OK'?'good':'warn'}">${status}</span></td></tr>`}).join('');$$('#account-center [data-account-store]').forEach(button=>button.addEventListener('click',()=>{state.store=button.dataset.accountStore;renderAll();switchView('overview');toast(`You switched to the home page of ${stores[state.store].name}`)}))}
