const loginForm=$('#login-form');function runWhenIdle(task){if('requestIdleCallback'in window)requestIdleCallback(task,{timeout:1600});else setTimeout(task,300)}function enterSystem(type){const admin=type==='admin';state.role=admin?'admin':'client';state.client=admin?'all':'daniel';state.store='zroyal';$('#role-select').value=state.role;$('#client-select').value=state.client;document.body.classList.add('authenticated');renderAll();refreshProductCosts().finally(()=>{refreshShopifyConnection();runWhenIdle(()=>Promise.allSettled([refreshSupplierConnection(),refreshEtsyConnections()]))});toast(admin?'You’re signed in as admin':'Welcome to your account')}
const urlLogin=new URLSearchParams(location.search);if(urlLogin.has('username')||urlLogin.has('password'))history.replaceState({},'',location.pathname+location.hash);
loginForm.addEventListener('submit',async e=>{e.preventDefault();const button=loginForm.querySelector('[type="submit"]'),error=$('[data-login-error]');if(button.disabled)return;button.disabled=true;error.hidden=true;try{const data=new FormData(loginForm),response=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:String(data.get('username')).trim(),password:String(data.get('password')),remember:data.get('remember')==='on'})}),result=await response.json().catch(()=>({}));if(response.ok&&result.ok){if(result.redirect){location.href=result.redirect;return}enterSystem(result.role)}else{error.textContent=response.status===401?'Incorrect username or password':'Can’t sign in right now. Please try again in a moment.';error.hidden=false}}catch{error.textContent='The connection didn’t complete. Check your internet connection and try again.';error.hidden=false}finally{button.disabled=false}});
