async function refreshEtsyConnections(){
  try{
    const response=await fetch('/api/etsy/status?fresh='+Date.now()),result=await response.json();
    if(!result.ok)throw new Error(result.error||'Etsy status failed');
    const connected=(result.shops||[]).filter(item=>item.connected).length;
    $$('.real-store-list [data-etsy-shop]').forEach(button=>{
      const item=(result.shops||[]).find(entry=>entry.shop===button.dataset.etsyShop),status=button.closest('article')?.querySelector('em');
      button.dataset.connected=String(Boolean(item?.connected));
      button.textContent=item?.connected?'Connection details':'Store connection';
      if(status){status.textContent=item?.connected?'Connected · LIVE':result.configured?'Ready to connect':'Secret still needed';status.className=item?.connected?'status success':'status warn'}
    });
    const readiness=$('.etsy-connect-board .connection-readiness');
    if(readiness){readiness.querySelector('b').textContent=`${connected} of 3 connected stores`;readiness.querySelector('small').textContent=result.configured?'App approved · each store can be connected through its own proxy':'App approved · still needs Shared Secret one-time'}
    const source=[...$$('.integration-list button')].find(node=>node.querySelector('b')?.textContent==='Etsy');
    if(source){source.querySelector('small').textContent=`${connected} of 3 connected stores`;const badge=source.querySelector('em');badge.textContent=connected===3?'Connected':connected?'In progress':'Ready';badge.className=connected===3?'status success':'status warn'}
    const params=new URLSearchParams(location.search);
    if(params.get('etsy')==='connected'){toast(`${params.get('shop')||'Store Etsy'} connected successfully`);history.replaceState({},'',location.pathname)}
  }catch(error){console.warn('Etsy connection status unavailable')}
}


async function refreshSupplierConnection(){
  try{
    const response=await fetch('/api/supplier/sync'),result=await response.json();
    if(!response.ok||!result.ok)throw new Error(result.error||'Supplier sync failed');
    supplierLive=result.data;
    supplierOrders=(result.data.orders||[]).map(row=>{const resolved=row.priceMatched&&Number.isFinite(Number(row.salePrice)),total=resolved?Number(row.salePrice)*Number(row.quantity||1):0,key=productIdentity(row),saved=loadProductCosts()[key]||{},product=Number.isFinite(Number(saved.product))?Number(saved.product):Number(row.supplierCost||0),shipping=Number.isFinite(Number(saved.shipping))?Number(saved.shipping):0,baseFees=resolved?feeFor('Etsy',total):0,fees=baseFees+(Number(saved.fees)||0),hasShipping=Number.isFinite(Number(saved.shipping));return{id:row.orderNumber||('ETSY-'+row.listingId),client:row.store,customer:row.customerName||'Customer Etsy',item:row.variant?row.title+' · '+row.variant:row.title,platform:'Etsy',channel:'Not connected',total,refund:0,shipping,product,fees,baseFees,costComplete:resolved&&hasShipping,status:row.shippingStatus,createdAt:row.date,source:'supplier-live',productKey:key,listingId:row.listingId,sku:row.sku,quantity:Number(row.quantity||1),priceSource:resolved?'Price Etsy public':'Sale price missing',trackingNumber:row.trackingNumber,courier:row.courier}});
    orders=[...shopifyOrders,...supplierOrders];
    Object.assign(stores.cursed,{status:'Supplier sheet · LIVE'});Object.assign(stores.select,{status:'Supplier sheet · LIVE'});Object.assign(stores.nerd,{status:'Supplier sheet · LIVE'});
    if(document.body.classList.contains('authenticated'))renderAll();
  }catch(error){console.warn('Supplier connection unavailable')}
}
const englishShopifyStatus=$$('.integration-list [data-shopify-store] .status')[0],englishShopifyKicker=$('.shopify-connect-copy span');if(englishShopifyStatus)englishShopifyStatus.id='shopify-source-status';if(englishShopifyKicker)englishShopifyKicker.id='shopify-board-kicker';
async function refreshShopifyConnection(force=false){
  const sourceStatus=document.querySelector('#shopify-source-status');
  const kicker=document.querySelector('#shopify-board-kicker');
  const board=document.querySelector('.shopify-connect-board');
  if(!sourceStatus||!board)return;
  try{
    const refreshButton=$('#refresh-data');
    if(refreshButton&&force){refreshButton.disabled=true;refreshButton.textContent='Refreshing…'}
    const response=await fetch('/api/shopify/sync'+(force?'?force=1':''),{method:'POST',headers:{'content-type':'application/json'}});
    const result=await response.json();
    if(!result.ok||!result.data?.connected)throw new Error(result.error||'Connection failed');
    const data=result.data;
    liveShopify=data;
    liveLoading=false;
    if(data.ordersAccess&&Array.isArray(data.orders)){
      const statusLabel=order=>order.cancelledAt?'Cancelled':order.displayFulfillmentStatus==='FULFILLED'?'Delivered':order.displayFulfillmentStatus==='PARTIALLY_FULFILLED'?'Partially shipped':order.displayFinancialStatus==='REFUNDED'?'Refunded':order.displayFinancialStatus==='PAID'?'Processing':'Pending';
      const savedCosts=loadLiveCosts();shopifyOrders=data.orders.map(order=>{const saved=savedCosts[order.name]||{},hasProduct=Number.isFinite(Number(saved.product))&&saved.product!=='',hasShipping=Number.isFinite(Number(saved.shipping))&&saved.shipping!=='';return{id:order.name,client:'Z‑Royal',customer:'Shopify',item:'Order from Shopify',platform:'Shopify',channel:'Not connected',total:Number(order.totalPriceSet?.shopMoney?.amount||0),refund:Number(order.totalRefundedSet?.shopMoney?.amount||0),shipping:hasShipping?Number(saved.shipping):0,product:hasProduct?Number(saved.product):0,fees:Number(saved.fees||0),costComplete:hasProduct&&hasShipping,status:statusLabel(order),createdAt:order.createdAt,source:'shopify-live'}});orders=[...shopifyOrders,...supplierOrders];
    }
    sourceStatus.textContent=data.ordersAccess?'Connected':'Connected · orders permission needed';
    sourceStatus.className=data.ordersAccess?'status success':'status warn';
    kicker.textContent=data.ordersAccess?'SHOPIFY Connected and synced':'SHOPIFY Connected';
    const copy=board.querySelector('.shopify-connect-copy');
    const action=board.querySelector('.shopify-connect-action');
    copy.querySelector('h2').textContent=data.ordersAccess?`${data.shop.name} connected in real time`:`${data.shop.name} Connected — orders permission missing`;
    copy.querySelector('p').innerHTML=data.ordersAccess?`Connection to <b>by-z-royal.myshopify.com</b> active. Data from Shopify available for automatic sync.`:`The store was verified successfully. To read sales and profitability you need to approve the <b>Orders</b> in Shopify.`;
    action.querySelector('em').textContent=data.ordersAccess?'Connected':'One approval needed';
    action.querySelector('button').textContent=data.ordersAccess?'Sync active ✓':'Open Shopify for approval';
    action.querySelector('button').onclick=()=>window.open('https://dev.shopify.com/dashboard','_blank','noopener');
    const sync=$('.sync-state');
    if(sync){const updated=data.syncedAt?new Intl.DateTimeFormat('en-US',{hour:'2-digit',minute:'2-digit'}).format(new Date(data.syncedAt)):'';sync.innerHTML=`<span class="live-dot"></span><div><b>Z‑Royal connected · LIVE</b><small>${data.summary?.orderCount||0} orders · updated ${updated}${data.refreshing?' · updating in background':''}</small></div>`}
    if(refreshButton){refreshButton.disabled=false;refreshButton.textContent='Refresh now'}
    renderAll();
  }catch(error){
    liveLoading=false;shopifyUnavailable=true;{const sync=$('.sync-state');if(sync)sync.innerHTML='<span class="live-dot" style="background:#c58a2b"></span><div><b>Shopify not connected yet</b><small>Waiting for the Shopify API keys</small></div>'}if(document.body.classList.contains('authenticated'))renderAll();
    sourceStatus.textContent='Needs checking';
    sourceStatus.className='status warn';
    const refreshButton=$('#refresh-data');if(refreshButton){refreshButton.disabled=false;refreshButton.textContent='Refresh now'}
  }
}
